//! Provides a [`tracing_subscriber::Layer`] ([`SpanStorageLayer`]) for capturing and storing
//! key-value data from tracing spans.

use std::{
    borrow::Cow,
    collections::{HashMap, HashSet},
    fmt,
    time::Instant,
};

use tracing::{
    Id, Subscriber,
    field::{Field, Visit},
    span::{Attributes, Record},
};
use tracing_subscriber::{Layer, layer::Context};

/// A [`tracing_subscriber::Layer`] that enables storing key-value data within span extensions.
/// It also handles propagation of "persistent" keys to parent spans and records span duration.
#[derive(Clone, Debug)]
pub struct SpanStorageLayer {
    persistent_keys: HashSet<&'static str>,
}

impl SpanStorageLayer {
    /// Creates a new [`SpanStorageLayer`] layer with the specified persistent keys.
    ///
    /// The values of persistent keys would be propagated to parent spans, if they are set or
    /// updated in the current span.
    pub fn new(persistent_keys: impl IntoIterator<Item = &'static str>) -> Self {
        Self {
            persistent_keys: HashSet::from_iter(persistent_keys),
        }
    }
}

/// Holds key-value data recorded for a span or an event.
///
/// This struct is typically stored in a span's extensions via [`SpanStorageLayer`].
#[derive(Clone, Debug, Default)]
pub struct Storage {
    /// The collected key-value pairs for the span.
    values: HashMap<Cow<'static, str>, serde_json::Value>,

    /// The primary message of an event, if captured.
    message: Option<String>,
}

impl Storage {
    /// Returns `true` if `key` is reserved by the logging infrastructure and cannot be recorded
    /// via [`Self::record_value`].
    ///
    /// The reserved keys are: `message`, `level`, `target`, `line`, `file`, `time`, `hostname`,
    /// `pid`, `thread_id`, `thread_name`, `fn`, `full_name`.
    /// This list may grow in future releases.
    pub fn is_reserved(key: &str) -> bool {
        super::keys::is_reserved(key)
    }

    /// Records a key-value pair into the storage.
    ///
    /// If `key` is reserved (see [`is_reserved()`][Self::is_reserved]), a warning is logged,
    /// and the value is not recorded.
    pub fn record_value(&mut self, key: impl Into<Cow<'static, str>>, value: serde_json::Value) {
        let key = key.into();
        if Self::is_reserved(&key) {
            tracing::warn!(
                "Attempting to record a reserved key `{key}` (value: {value:?}). Skipping."
            );
        } else {
            self.values.insert(key, value);
        }
    }

    /// Returns the key-value pairs recorded in this storage.
    pub fn values(&self) -> &HashMap<Cow<'static, str>, serde_json::Value> {
        &self.values
    }

    /// Returns the primary message of an event, if captured.
    pub fn message(&self) -> Option<&str> {
        self.message.as_deref()
    }

    /// Runs `f` with the [`Storage`] of the current span, if any.
    ///
    /// Returns `None` if any of the following conditions hold:
    ///
    /// - There is no current span.
    /// - The current subscriber is not a [`Registry`][tracing_subscriber::Registry]-based
    ///   subscriber using [`SpanStorageLayer`].
    /// - The current span has no [`Storage`] associated with it.
    ///
    /// Use [`with_current_span_mut()`][Self::with_current_span_mut] to record values into the storage.
    #[cfg_attr(
        all(not(feature = "tracing-storage-api"), not(test)),
        expect(dead_code)
    )]
    pub fn with_current_span<T>(f: impl FnOnce(&Self) -> T) -> Option<T> {
        use tracing_subscriber::{Registry, registry::LookupSpan};

        tracing::Span::current()
            .with_subscriber(|(id, dispatch)| {
                let registry = dispatch.downcast_ref::<Registry>()?;
                let span = registry.span(id)?;
                let extensions = span.extensions();
                let storage = extensions.get::<Self>()?;

                Some(f(storage))
            })
            .flatten()
    }

    /// Runs `f` with the [`Storage`] of the current span, if any.
    ///
    /// Returns `None` if any of the following conditions hold:
    ///
    /// - There is no current span.
    /// - The current subscriber is not a [`Registry`][tracing_subscriber::Registry]-based
    ///   subscriber using [`SpanStorageLayer`].
    /// - The current span has no [`Storage`] associated with it.
    ///
    /// Use [`Self::with_current_span`] to read the storage without modifying it.
    #[cfg_attr(
        all(not(feature = "tracing-storage-api"), not(test)),
        expect(dead_code)
    )]
    pub fn with_current_span_mut<T>(f: impl FnOnce(&mut Self) -> T) -> Option<T> {
        use tracing_subscriber::{Registry, registry::LookupSpan};

        tracing::Span::current()
            .with_subscriber(|(id, dispatch)| {
                let registry = dispatch.downcast_ref::<Registry>()?;
                let span = registry.span(id)?;
                let mut extensions = span.extensions_mut();
                let storage = extensions.get_mut::<Self>()?;

                Some(f(storage))
            })
            .flatten()
    }
}

// Implement `Visit` to capture span or event fields into the `Storage` map.
//
// `field.name()` returns `&'static str` (field names are baked into the binary by `tracing`),
// so `record_value` receives `&'static str` → `Cow::Borrowed` — zero allocation for declared
// span fields.
impl Visit for Storage {
    fn record_f64(&mut self, field: &Field, value: f64) {
        if field.name() == super::keys::MESSAGE {
            if self.message.is_none() {
                self.message = Some(value.to_string());
            }
        } else {
            self.record_value(field.name(), serde_json::Value::from(value));
        }
    }

    fn record_i64(&mut self, field: &Field, value: i64) {
        if field.name() == super::keys::MESSAGE {
            if self.message.is_none() {
                self.message = Some(value.to_string());
            }
        } else {
            self.record_value(field.name(), serde_json::Value::from(value));
        }
    }

    fn record_u64(&mut self, field: &Field, value: u64) {
        if field.name() == super::keys::MESSAGE {
            if self.message.is_none() {
                self.message = Some(value.to_string());
            }
        } else {
            self.record_value(field.name(), serde_json::Value::from(value));
        }
    }

    fn record_bool(&mut self, field: &Field, value: bool) {
        if field.name() == super::keys::MESSAGE {
            if self.message.is_none() {
                self.message = Some(value.to_string());
            }
        } else {
            self.record_value(field.name(), serde_json::Value::from(value));
        }
    }

    fn record_str(&mut self, field: &Field, value: &str) {
        if field.name() == super::keys::MESSAGE {
            self.message = Some(value.to_string()); // `record_str()` is preferred for `message`
        } else {
            self.record_value(field.name(), serde_json::Value::from(value));
        }
    }

    fn record_debug(&mut self, field: &Field, value: &dyn fmt::Debug) {
        if field.name() == super::keys::MESSAGE {
            if self.message.is_none() {
                // Only use debug if `record_str()` hasn't set it
                self.message = Some(format!("{value:?}"));
            }
        } else {
            match field.name() {
                // Skip fields which are already handled
                name if name.starts_with("log.") => (),
                name if name.starts_with("r#") => {
                    #[expect(clippy::expect_used)]
                    let stripped = name
                        .get(2..)
                        .expect(
                            "field name using raw identifiers must have at least two characters",
                        )
                        .to_owned();
                    // Raw identifier prefix is stripped, so we need an owned key
                    self.record_value(stripped, serde_json::Value::from(format!("{value:?}")));
                }
                name => {
                    self.record_value(name, serde_json::Value::from(format!("{value:?}")));
                }
            };
        }
    }
}

impl<S: Subscriber + for<'a> tracing_subscriber::registry::LookupSpan<'a>> Layer<S>
    for SpanStorageLayer
{
    fn on_new_span(&self, attrs: &Attributes<'_>, id: &Id, ctx: Context<'_, S>) {
        #[expect(clippy::expect_used)]
        let span = ctx
            .span(id)
            .expect("span with specified id does not exist in `on_new_span()`");
        let mut extensions = span.extensions_mut();

        // Inherit storage from parent span if it exists, otherwise create a new span.
        let mut visitor = if let Some(parent_span) = span.parent() {
            parent_span
                .extensions()
                .get::<Storage>()
                .cloned()
                .unwrap_or_default()
        } else {
            Storage::default()
        };

        attrs.record(&mut visitor);
        extensions.insert(visitor);
    }

    fn on_record(&self, span_id: &Id, values: &Record<'_>, ctx: Context<'_, S>) {
        #[expect(clippy::expect_used)]
        let span = ctx
            .span(span_id)
            .expect("span with specified id does not exist in `on_record()`");
        let mut extensions = span.extensions_mut();

        #[expect(clippy::expect_used)]
        let visitor = extensions
            .get_mut::<Storage>()
            .expect("span does not have storage in `on_record()`");

        values.record(visitor);
    }

    fn on_enter(&self, span_id: &Id, ctx: Context<'_, S>) {
        #[expect(clippy::expect_used)]
        let span = ctx
            .span(span_id)
            .expect("span with specified id does not exist in `on_enter()`");
        let mut extensions = span.extensions_mut();

        // Store the current time in the span if it doesn't already exist
        if extensions.get_mut::<Instant>().is_none() {
            extensions.insert(Instant::now());
        }
    }

    fn on_close(&self, id: Id, ctx: Context<'_, S>) {
        #[expect(clippy::expect_used)]
        let span = ctx
            .span(&id)
            .expect("span with specified id does not exist in `on_close()`");

        let elapsed_milliseconds = span
            .extensions()
            .get::<Instant>()
            .map(|i| i.elapsed().as_millis())
            .unwrap_or(0);

        // Propagate persistent keys to parent
        if let Some(storage) = span.extensions().get::<Storage>() {
            storage
                .values
                .iter()
                .filter(|(k, _v)| self.persistent_keys.contains(k.as_ref()))
                .for_each(|(k, v)| {
                    span.parent().and_then(|parent_span| {
                        parent_span
                            .extensions_mut()
                            .get_mut::<Storage>()
                            .map(|parent_storage| {
                                parent_storage.record_value(k.clone(), v.clone());
                            })
                    });
                });
        }

        let mut extensions = span.extensions_mut();
        #[expect(clippy::expect_used)]
        let visitor = extensions
            .get_mut::<Storage>()
            .expect("span does not have storage in `on_close()`");

        // Record elapsed time in the span's storage
        if let Ok(elapsed_time_value) = serde_json::to_value(elapsed_milliseconds) {
            visitor.record_value(super::keys::ELAPSED_MILLISECONDS, elapsed_time_value);
        }
    }
}

//! Structure describing secret.

use std::{fmt, marker::PhantomData};

use subtle::ConstantTimeEq;
use zeroize::{self, Zeroize as ZeroizableSecret};

use crate::{PeekInterface, strategy::Strategy};

/// Secret thing.
///
/// To get access to value use method `expose()` of trait [`crate::ExposeInterface`].
pub struct StrongSecret<Secret: ZeroizableSecret, MaskingStrategy = crate::WithType> {
    /// Inner secret value
    pub(crate) inner_secret: Secret,
    pub(crate) masking_strategy: PhantomData<MaskingStrategy>,
}

impl<Secret: ZeroizableSecret, MaskingStrategy> StrongSecret<Secret, MaskingStrategy> {
    /// Take ownership of a secret value
    pub fn new(secret: Secret) -> Self {
        Self {
            inner_secret: secret,
            masking_strategy: PhantomData,
        }
    }
}

impl<Secret: ZeroizableSecret, MaskingStrategy> PeekInterface<Secret>
    for StrongSecret<Secret, MaskingStrategy>
{
    fn peek(&self) -> &Secret {
        &self.inner_secret
    }

    fn peek_mut(&mut self) -> &mut Secret {
        &mut self.inner_secret
    }
}

impl<Secret: ZeroizableSecret, MaskingStrategy> From<Secret>
    for StrongSecret<Secret, MaskingStrategy>
{
    fn from(secret: Secret) -> Self {
        Self::new(secret)
    }
}

impl<Secret: Clone + ZeroizableSecret, MaskingStrategy> Clone
    for StrongSecret<Secret, MaskingStrategy>
{
    fn clone(&self) -> Self {
        Self {
            inner_secret: self.inner_secret.clone(),
            masking_strategy: PhantomData,
        }
    }
}

impl<Secret, MaskingStrategy> PartialEq for StrongSecret<Secret, MaskingStrategy>
where
    Self: PeekInterface<Secret>,
    Secret: ZeroizableSecret + StrongEq,
{
    fn eq(&self, other: &Self) -> bool {
        StrongEq::strong_eq(self.peek(), other.peek())
    }
}

impl<Secret, MaskingStrategy> Eq for StrongSecret<Secret, MaskingStrategy>
where
    Self: PeekInterface<Secret>,
    Secret: ZeroizableSecret + StrongEq,
{
}

impl<Secret: ZeroizableSecret, MaskingStrategy: Strategy<Secret>> fmt::Debug
    for StrongSecret<Secret, MaskingStrategy>
{
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        MaskingStrategy::fmt(&self.inner_secret, f)
    }
}

impl<Secret: ZeroizableSecret, MaskingStrategy> Default for StrongSecret<Secret, MaskingStrategy>
where
    Secret: ZeroizableSecret + Default,
{
    fn default() -> Self {
        Secret::default().into()
    }
}

impl<Secret: ZeroizableSecret, MaskingStrategy> Drop for StrongSecret<Secret, MaskingStrategy> {
    fn drop(&mut self) {
        self.inner_secret.zeroize();
    }
}

trait StrongEq {
    fn strong_eq(&self, other: &Self) -> bool;
}

impl StrongEq for String {
    fn strong_eq(&self, other: &Self) -> bool {
        let lhs = self.as_bytes();
        let rhs = other.as_bytes();

        bool::from(lhs.ct_eq(rhs))
    }
}

impl StrongEq for Vec<u8> {
    fn strong_eq(&self, other: &Self) -> bool {
        let lhs = &self;
        let rhs = &other;

        bool::from(lhs.ct_eq(rhs))
    }
}

#[cfg(feature = "proto_tonic")]
impl<T> prost::Message for StrongSecret<T, crate::WithType>
where
    T: prost::Message + Default + Clone + ZeroizableSecret,
{
    fn encode_raw(&self, buf: &mut impl bytes::BufMut) {
        self.peek().encode_raw(buf);
    }

    fn merge_field(
        &mut self,
        tag: u32,
        wire_type: prost::encoding::WireType,
        buf: &mut impl bytes::Buf,
        ctx: prost::encoding::DecodeContext,
    ) -> Result<(), prost::DecodeError> {
        if tag == 1 {
            self.peek_mut().merge_field(tag, wire_type, buf, ctx)
        } else {
            prost::encoding::skip_field(wire_type, tag, buf, ctx)
        }
    }

    fn encoded_len(&self) -> usize {
        self.peek().encoded_len()
    }

    fn clear(&mut self) {
        self.peek_mut().clear();
    }
}

//! Structure describing secret.

use std::{fmt, marker::PhantomData};

use crate::{PeekInterface, StrongSecret, strategy::Strategy};

/// Secret thing.
///
/// To get access to value use method `expose()` of trait [`crate::ExposeInterface`].
///
/// ## Masking
/// Use the [`crate::strategy::Strategy`] trait to implement a masking strategy on a zero-variant
/// enum and pass this enum as a second generic parameter to [`Secret`] while defining it.
/// [`Secret`] will take care of applying the masking strategy on the inner secret when being
/// displayed.
///
/// ## Masking Example
///
/// ```
/// use std::fmt;
///
/// use hyperswitch_masking::{Secret, Strategy};
///
/// enum MyStrategy {}
///
/// impl<T> Strategy<T> for MyStrategy
/// where
///     T: fmt::Display,
/// {
///     fn fmt(val: &T, f: &mut fmt::Formatter<'_>) -> fmt::Result {
///         write!(f, "{}", val.to_string().to_ascii_lowercase())
///     }
/// }
///
/// let my_secret: Secret<String, MyStrategy> = Secret::new("HELLO".to_string());
///
/// assert_eq!("hello", &format!("{:?}", my_secret));
/// ```
pub struct Secret<Secret, MaskingStrategy = crate::WithType>
where
    MaskingStrategy: Strategy<Secret>,
{
    pub(crate) inner_secret: Secret,
    pub(crate) masking_strategy: PhantomData<MaskingStrategy>,
}

impl<SecretValue, MaskingStrategy> Secret<SecretValue, MaskingStrategy>
where
    MaskingStrategy: Strategy<SecretValue>,
{
    /// Take ownership of a secret value
    pub fn new(secret: SecretValue) -> Self {
        Self {
            inner_secret: secret,
            masking_strategy: PhantomData,
        }
    }

    /// Zip 2 secrets with the same masking strategy into one
    pub fn zip<OtherSecretValue>(
        self,
        other: Secret<OtherSecretValue, MaskingStrategy>,
    ) -> Secret<(SecretValue, OtherSecretValue), MaskingStrategy>
    where
        MaskingStrategy: Strategy<OtherSecretValue> + Strategy<(SecretValue, OtherSecretValue)>,
    {
        (self.inner_secret, other.inner_secret).into()
    }

    /// consume self and modify the inner value
    pub fn map<OtherSecretValue>(
        self,
        f: impl FnOnce(SecretValue) -> OtherSecretValue,
    ) -> Secret<OtherSecretValue, MaskingStrategy>
    where
        MaskingStrategy: Strategy<OtherSecretValue>,
    {
        f(self.inner_secret).into()
    }

    /// Convert to [`StrongSecret`]
    pub fn into_strong(self) -> StrongSecret<SecretValue, MaskingStrategy>
    where
        SecretValue: zeroize::DefaultIsZeroes,
    {
        StrongSecret::new(self.inner_secret)
    }

    /// Convert to [`Secret`] with a reference to the inner secret
    pub fn as_ref(&self) -> Secret<&SecretValue, MaskingStrategy>
    where
        MaskingStrategy: for<'a> Strategy<&'a SecretValue>,
    {
        Secret::new(self.peek())
    }
}

impl<SecretValue, MaskingStrategy> PeekInterface<SecretValue>
    for Secret<SecretValue, MaskingStrategy>
where
    MaskingStrategy: Strategy<SecretValue>,
{
    fn peek(&self) -> &SecretValue {
        &self.inner_secret
    }

    fn peek_mut(&mut self) -> &mut SecretValue {
        &mut self.inner_secret
    }
}

impl<SecretValue, MaskingStrategy> From<SecretValue> for Secret<SecretValue, MaskingStrategy>
where
    MaskingStrategy: Strategy<SecretValue>,
{
    fn from(secret: SecretValue) -> Self {
        Self::new(secret)
    }
}

impl<SecretValue, MaskingStrategy> Clone for Secret<SecretValue, MaskingStrategy>
where
    SecretValue: Clone,
    MaskingStrategy: Strategy<SecretValue>,
{
    fn clone(&self) -> Self {
        Self {
            inner_secret: self.inner_secret.clone(),
            masking_strategy: PhantomData,
        }
    }
}

impl<SecretValue, MaskingStrategy> PartialEq for Secret<SecretValue, MaskingStrategy>
where
    Self: PeekInterface<SecretValue>,
    SecretValue: PartialEq,
    MaskingStrategy: Strategy<SecretValue>,
{
    fn eq(&self, other: &Self) -> bool {
        self.peek().eq(other.peek())
    }
}

impl<SecretValue, MaskingStrategy> Eq for Secret<SecretValue, MaskingStrategy>
where
    Self: PeekInterface<SecretValue>,
    SecretValue: Eq,
    MaskingStrategy: Strategy<SecretValue>,
{
}

impl<SecretValue, MaskingStrategy> std::hash::Hash for Secret<SecretValue, MaskingStrategy>
where
    Self: PeekInterface<SecretValue>,
    SecretValue: std::hash::Hash,
    MaskingStrategy: Strategy<SecretValue>,
{
    fn hash<H: std::hash::Hasher>(&self, state: &mut H) {
        self.peek().hash(state);
    }
}

impl<SecretValue, MaskingStrategy> fmt::Debug for Secret<SecretValue, MaskingStrategy>
where
    MaskingStrategy: Strategy<SecretValue>,
{
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        MaskingStrategy::fmt(&self.inner_secret, f)
    }
}

impl<SecretValue, MaskingStrategy> Default for Secret<SecretValue, MaskingStrategy>
where
    SecretValue: Default,
    MaskingStrategy: Strategy<SecretValue>,
{
    fn default() -> Self {
        SecretValue::default().into()
    }
}

// Required by base64-serde to serialize Secret of Vec<u8> which contains the base64 decoded value
impl AsRef<[u8]> for Secret<Vec<u8>> {
    fn as_ref(&self) -> &[u8] {
        self.peek().as_slice()
    }
}

/// Strategy for masking JSON values
#[cfg(feature = "serde")]
#[derive(Debug, Copy, Clone)]
pub enum JsonMaskStrategy {}

#[cfg(feature = "serde")]
impl Strategy<serde_json::Value> for JsonMaskStrategy {
    fn fmt(value: &serde_json::Value, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match value {
            serde_json::Value::Object(map) => {
                write!(f, "{{")?;
                let mut first = true;
                for (key, val) in map {
                    if !first {
                        write!(f, ", ")?;
                    }
                    first = false;
                    write!(f, "\"{key}\":")?;
                    Self::fmt(val, f)?;
                }
                write!(f, "}}")
            }
            serde_json::Value::Array(arr) => {
                write!(f, "[")?;
                let mut first = true;
                for val in arr {
                    if !first {
                        write!(f, ", ")?;
                    }
                    first = false;
                    Self::fmt(val, f)?;
                }
                write!(f, "]")
            }
            serde_json::Value::String(s) => {
                // For strings, we show a masked version that gives a hint about the content
                // String::chars().count() is an approximation and could be greater than
                // the actual "character" count, since it does not consider graphemes (what we
                // usually consider as a "character"). To be more accurate at the cost of some
                // performance we can use "graphemes()" from the unicode-segmentation crate
                let char_count = s.chars().count();
                let masked = if char_count <= 2 {
                    "**".to_string()
                } else if char_count <= 6 {
                    let first = s.chars().next().unwrap_or('*');
                    format!("{first}**")
                } else {
                    // For longer strings, show first and last character with length in between
                    let first = s.chars().next().unwrap_or('*');
                    let last = s.chars().last().unwrap_or('*');
                    format!("{first}**{count}**{last}", count = char_count - 2)
                };
                write!(f, "\"{masked}\"")
            }
            serde_json::Value::Number(n) => {
                // For numbers, we can show the order of magnitude
                if n.is_i64() || n.is_u64() {
                    let num_str = n.to_string();
                    let masked_num = "*".repeat(num_str.len());
                    write!(f, "{masked_num}")
                } else if n.is_f64() {
                    // For floats, just use a generic mask
                    write!(f, "**.**")
                } else {
                    write!(f, "0")
                }
            }
            serde_json::Value::Bool(b) => {
                // For booleans, we can show a hint about which one it is
                write!(f, "{}", if *b { "**true" } else { "**false" })
            }
            serde_json::Value::Null => write!(f, "null"),
        }
    }
}

#[cfg(feature = "proto_tonic")]
impl<T> prost::Message for Secret<T, crate::WithType>
where
    T: prost::Message + Default + Clone,
{
    fn encode_raw(&self, buf: &mut impl bytes::BufMut) {
        self.peek().encode_raw(buf);
    }

    fn merge_field(
        &mut self,
        tag: u32,
        wire_type: prost::encoding::WireType,
        buf: &mut impl bytes::Buf,
        ctx: prost::encoding::DecodeContext,
    ) -> Result<(), prost::DecodeError> {
        if tag == 1 {
            self.peek_mut().merge_field(tag, wire_type, buf, ctx)
        } else {
            prost::encoding::skip_field(wire_type, tag, buf, ctx)
        }
    }

    fn encoded_len(&self) -> usize {
        self.peek().encoded_len()
    }

    fn clear(&mut self) {
        self.peek_mut().clear();
    }
}

#[cfg(test)]
mod hash_tests {
    use std::hash::{DefaultHasher, Hash, Hasher};

    use super::*;

    #[test]
    fn test_secret_hash_implementation() {
        let secret1: Secret<String> = Secret::new("test_string".to_string());
        let secret2: Secret<String> = Secret::new("test_string".to_string());
        let secret3: Secret<String> = Secret::new("different_string".to_string());

        // Test that equal secrets hash to the same value
        let mut hasher1 = DefaultHasher::new();
        let mut hasher2 = DefaultHasher::new();
        secret1.hash(&mut hasher1);
        secret2.hash(&mut hasher2);
        assert_eq!(hasher1.finish(), hasher2.finish());

        // Test that different secrets hash to different values (usually)
        let mut hasher3 = DefaultHasher::new();
        secret3.hash(&mut hasher3);
        assert_ne!(hasher1.finish(), hasher3.finish());
    }
}

#[cfg(test)]
#[cfg(feature = "serde")]
mod tests {
    use serde_json::json;

    use super::*;

    #[test]
    fn test_json_mask_strategy() {
        // Create a sample JSON with different types for testing
        let original = json!({ "user": { "name": "John Doe", "email": "john@example.com", "age": 35, "verified": true }, "card": { "number": "4242424242424242", "cvv": 123, "amount": 99.99 }, "tags": ["personal", "premium"], "null_value": null, "short": "hi" });

        // Apply the JsonMaskStrategy
        let secret = Secret::<_, JsonMaskStrategy>::new(original.clone());
        let masked_str = format!("{secret:?}");

        // Get specific values from original
        let original_obj = original.as_object().expect("Original should be an object");
        let user_obj = original_obj["user"]
            .as_object()
            .expect("User should be an object");
        let name = user_obj["name"].as_str().expect("Name should be a string");
        let email = user_obj["email"]
            .as_str()
            .expect("Email should be a string");
        let age = user_obj["age"].as_i64().expect("Age should be a number");
        let verified = user_obj["verified"]
            .as_bool()
            .expect("Verified should be a boolean");

        let card_obj = original_obj["card"]
            .as_object()
            .expect("Card should be an object");
        let card_number = card_obj["number"]
            .as_str()
            .expect("Card number should be a string");
        let cvv = card_obj["cvv"].as_i64().expect("CVV should be a number");

        let tags = original_obj["tags"]
            .as_array()
            .expect("Tags should be an array");
        let tag1 = tags
            .first()
            .and_then(|v| v.as_str())
            .expect("First tag should be a string");

        // Now explicitly verify the masking patterns for each value type

        // 1. String masking - pattern: first char + ** + length - 2 + ** + last char
        let expected_name_mask = format!(
            "\"{}**{}**{}\"",
            name.chars().next().unwrap(),
            name.chars().count() - 2,
            name.chars().last().unwrap()
        );
        let expected_email_mask = format!(
            "\"{}**{}**{}\"",
            email.chars().next().unwrap(),
            email.chars().count() - 2,
            email.chars().last().unwrap()
        );
        let expected_card_mask = format!(
            "\"{}**{}**{}\"",
            card_number.chars().next().unwrap(),
            card_number.chars().count() - 2,
            card_number.chars().last().unwrap()
        );
        let expected_tag1_mask = if tag1.chars().count() <= 2 {
            "\"**\"".to_string()
        } else if tag1.chars().count() <= 6 {
            format!("\"{}**\"", tag1.chars().next().unwrap())
        } else {
            format!(
                "\"{}**{}**{}\"",
                tag1.chars().next().unwrap(),
                tag1.chars().count() - 2,
                tag1.chars().last().unwrap()
            )
        };
        let expected_short_mask = "\"**\"".to_string(); // For "hi"

        // 2. Number masking
        let expected_age_mask = "*".repeat(age.to_string().len()); // Repeat * for the number of digits
        let expected_cvv_mask = "*".repeat(cvv.to_string().len());

        // 3. Boolean masking
        let expected_verified_mask = if verified { "**true" } else { "**false" };

        // Check that the masked output includes the expected masked patterns
        assert!(
            masked_str.contains(&expected_name_mask),
            "Name not masked correctly. Expected: {expected_name_mask}"
        );
        assert!(
            masked_str.contains(&expected_email_mask),
            "Email not masked correctly. Expected: {expected_email_mask}",
        );
        assert!(
            masked_str.contains(&expected_card_mask),
            "Card number not masked correctly. Expected: {expected_card_mask}",
        );
        assert!(
            masked_str.contains(&expected_tag1_mask),
            "Tag not masked correctly. Expected: {expected_tag1_mask}",
        );
        assert!(
            masked_str.contains(&expected_short_mask),
            "Short string not masked correctly. Expected: {expected_short_mask}",
        );

        assert!(
            masked_str.contains(&expected_age_mask),
            "Age not masked correctly. Expected: {expected_age_mask}",
        );
        assert!(
            masked_str.contains(&expected_cvv_mask),
            "CVV not masked correctly. Expected: {expected_cvv_mask}",
        );

        assert!(
            masked_str.contains(expected_verified_mask),
            "Boolean not masked correctly. Expected: {expected_verified_mask}",
        );

        // Check structure preservation
        assert!(
            masked_str.contains("\"user\""),
            "Structure not preserved - missing user object"
        );
        assert!(
            masked_str.contains("\"card\""),
            "Structure not preserved - missing card object"
        );
        assert!(
            masked_str.contains("\"tags\""),
            "Structure not preserved - missing tags array"
        );
        assert!(
            masked_str.contains("\"null_value\":null"),
            "Null value not preserved correctly"
        );

        // Additional security checks to ensure no original values are exposed
        assert!(
            !masked_str.contains(name),
            "Original name value exposed in masked output"
        );
        assert!(
            !masked_str.contains(email),
            "Original email value exposed in masked output"
        );
        assert!(
            !masked_str.contains(card_number),
            "Original card number exposed in masked output"
        );
        assert!(
            !masked_str.contains(&age.to_string()),
            "Original age value exposed in masked output"
        );
        assert!(
            !masked_str.contains(&cvv.to_string()),
            "Original CVV value exposed in masked output"
        );
        assert!(
            !masked_str.contains(tag1),
            "Original tag value exposed in masked output"
        );
        assert!(
            !masked_str.contains("hi"),
            "Original short string value exposed in masked output"
        );
    }

    #[test]
    fn test_unicode_masking_safety() {
        // This test ensures that masking does not panic on multi-byte unicode characters,
        // and that the output is as expected.
        let unicode_test_cases = vec![
            ("ü", r#""**""#),                                      // 1 char <= 2
            ("😀", r#""**""#),                                     // 1 char <= 2
            ("überspringen", r#""ü**10**n""#),                     // 12 chars > 6
            ("end with ü", r#""e**8**ü""#),                        // 10 chars > 6
            ("😀-a-long-string-with-emoji-😀", r#""😀**26**😀""#), // 28 chars > 6
            ("a", r#""**""#),                                      // 1 char <= 2
            ("ab", r#""**""#),                                     // 2 chars <= 2
            ("abc", r#""a**""#),                                   // 3 chars <= 6
            ("abcdef", r#""a**""#),                                // 6 chars <= 6
            ("abcdefg", r#""a**5**g""#),                           // 7 chars > 6
            ("Homyel’ Voblasc’", r#""H**14**’""#),
            ("кпукпукп", r#""к**6**п""#),
        ];

        for (input, expected_mask) in unicode_test_cases {
            let json = json!({ "key": input });
            let secret = Secret::<_, JsonMaskStrategy>::new(json);
            let masked_str = format!("{secret:?}");
            let expected_output = format!(r#"{{"key":{}}}"#, expected_mask);
            assert_eq!(masked_str, expected_output, "Failed for input: '{}'", input);
        }
    }
}

//! Tracing-based logging infrastructure.
//!
//! This module is only available when the `tracing` feature is enabled.

mod formatter;
mod storage;

use std::collections::{HashMap, HashSet};

use serde_json::Value;
pub use tracing::Level;
pub use tracing_appender::rolling::Rotation;
use tracing_subscriber::{EnvFilter, Layer};

#[cfg_attr(
    all(not(feature = "tracing-storage-api"), not(test)),
    expect(unused_imports)
)]
pub use self::storage::Storage;
pub use self::{
    formatter::{JsonFormattingLayer, JsonFormattingLayerConfig, RecordType},
    storage::SpanStorageLayer,
};

mod keys {
    use std::sync::LazyLock;

    use rustc_hash::FxHashSet;

    pub(crate) const MESSAGE: &str = "message";
    pub(crate) const LEVEL: &str = "level";
    pub(crate) const TARGET: &str = "target";
    pub(crate) const LINE: &str = "line";
    pub(crate) const FILE: &str = "file";
    pub(crate) const TIME: &str = "time";
    pub(crate) const HOSTNAME: &str = "hostname";
    pub(crate) const PID: &str = "pid";
    pub(crate) const THREAD_ID: &str = "thread_id";
    pub(crate) const THREAD_NAME: &str = "thread_name";
    pub(crate) const FN: &str = "fn";
    pub(crate) const FULL_NAME: &str = "full_name";
    pub(crate) const ELAPSED_MILLISECONDS: &str = "elapsed_milliseconds";

    // If you add or remove a key in this list, also update the list documented on
    // `Storage::is_reserved()`.
    static RESERVED_KEYS: LazyLock<FxHashSet<&'static str>> = LazyLock::new(|| {
        [
            MESSAGE,
            LEVEL,
            TARGET,
            LINE,
            FILE,
            TIME,
            HOSTNAME,
            PID,
            THREAD_ID,
            THREAD_NAME,
            FN,
            FULL_NAME,
        ]
        .iter()
        .copied()
        .collect()
    });

    pub(crate) fn is_reserved(key: &str) -> bool {
        RESERVED_KEYS.contains(key)
    }
}

/// Comprehensive configuration for the entire logging system.
#[derive(Debug, Clone)]
pub struct LoggerConfig {
    /// A map of key-value pairs that are statically defined at initialization and included
    /// at the top level of every log entry.
    pub static_top_level_fields: HashMap<String, Value>,

    /// A set of keys which will be promoted to the top level of the JSON output,
    /// if they appear in a log event or span's dynamic data.
    pub top_level_keys: HashSet<&'static str>,

    /// Keys whose values from spans should be propagated to parent spans,
    /// if they set in the current span.
    /// This is useful for capturing context that should be visible in parent spans,
    /// such as merchant IDs, user IDs, etc.
    pub persistent_keys: HashSet<&'static str>,

    /// If `true`, logs all span entries and exits.
    /// If `false`, does not log span entries and only logs exits for root spans.
    pub log_span_lifecycles: bool,

    /// Specifies how additional fields (not designated as top-level) are placed in the JSON output.
    pub additional_fields_placement: AdditionalFieldsPlacement,

    /// Configuration for file logging. If `None`, file logging is disabled.
    pub file_config: Option<FileLoggingConfig>,

    /// Configuration for console logging. If `None`, console logging is disabled.
    pub console_config: Option<ConsoleLoggingConfig>,

    /// A global [`EnvFilter`] directive (e.g., `"info,my_crate=debug"`) for filtering log events.
    /// This directive may be overridden by specific directives in
    /// [`FileLoggingConfig`] or [`ConsoleLoggingConfig`].
    /// This allows using a less verbose log level for third-party crates,
    /// while using a more verbose level for first-party crates, for example.
    pub global_filtering_directive: Option<String>,
}

/// Configuration for file logging.
#[derive(Debug, Clone)]
pub struct FileLoggingConfig {
    /// Directory where log files will be stored.
    pub directory: String,

    /// Prefix for log file names.
    pub file_name_prefix: String,

    /// Rotation strategy for log files.
    pub file_rotation: Rotation,

    /// Maximum number of log files to keep. If `None`, all files are kept.
    pub max_log_files: Option<std::num::NonZeroUsize>,

    /// Minimum log level for file logs.
    pub level: Level,

    /// [`EnvFilter`] directive specific to file logs, overriding the global filtering directive.
    /// If `None`, the global filtering directive is used.
    pub filtering_directive: Option<String>,

    /// Specifies where to print the effective filtering directive for file logs.
    pub print_filtering_directive: DirectivePrintTarget,
}

/// Configuration for console logging.
#[derive(Debug, Clone)]
pub struct ConsoleLoggingConfig {
    /// Minimum log level for console logs.
    pub level: Level,

    /// Output format for console logs.
    pub log_format: ConsoleLogFormat,

    /// [`EnvFilter`] directive specific to console logs, overriding the global filtering directive.
    /// If `None`, the global filtering directive is used.
    pub filtering_directive: Option<String>,

    /// Specifies where to print the effective filtering directive for console logs.
    pub print_filtering_directive: DirectivePrintTarget,
}

/// Specifies where (if at all) to print the effective filtering directive during logger setup.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum DirectivePrintTarget {
    /// Print to standard output.
    Stdout,

    /// Print to standard error.
    Stderr,

    /// Do not print the directive.
    None,
}

/// Defines the output format for console logging.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ConsoleLogFormat {
    /// Pretty-printed, human-readable, multi-line format.
    HumanReadable,

    /// Compact, single-line JSON format.
    CompactJson,

    /// Pretty-printed, multi-line JSON format.
    PrettyJson,
}

/// Defines how additional (non-top-level, non-implicit) fields are placed in the JSON log output.
#[derive(Debug, Clone)]
pub enum AdditionalFieldsPlacement {
    /// Log all additional fields at the top level of the JSON object.
    TopLevel,

    /// Nest all additional fields under the specified key.
    Nested(String),
}

impl AdditionalFieldsPlacement {
    pub(crate) fn is_nested(&self) -> bool {
        matches!(self, Self::Nested(_))
    }
}

/// Holds the constructed logging layers and their associated worker guards.
/// These components can be combined with other layers and a [`tracing_subscriber::Registry`]
/// before initializing the global subscriber.
#[expect(missing_debug_implementations)] // File and console layers are `dyn Trait` objects
pub struct LoggingComponents {
    /// The layer responsible for storing span data.
    pub storage_layer: SpanStorageLayer,

    /// The file logging layer, if enabled and configured.
    pub file_log_layer:
        Option<Box<dyn Layer<tracing_subscriber::Registry> + Send + Sync + 'static>>,

    /// The console logging layer, if enabled and configured.
    pub console_log_layer:
        Option<Box<dyn Layer<tracing_subscriber::Registry> + Send + Sync + 'static>>,

    /// Worker guards for file and console logging layers.
    /// Logs would be written as long as these guards are in scope.
    pub guards: Vec<tracing_appender::non_blocking::WorkerGuard>,
}

/// Errors that can occur within the logger.
#[derive(Debug, thiserror::Error)]
pub enum LoggerError {
    /// Represents an error in configuration.
    #[error("Configuration error: {0}")]
    Configuration(String),

    /// Represents an error during JSON serialization.
    #[error("JSON serialization error: {0}")]
    JsonSerialization(#[from] serde_json::Error),

    /// Represents an error during initialization of the rolling file appender.
    #[error("Failed to initialize rolling file appender: {0}")]
    FileAppenderInitialization(#[from] tracing_appender::rolling::InitError),

    /// Represents an error due to an invalid filtering directive.
    #[error("Failed to parse filtering directive: {0}")]
    InvalidFilteringDirective(#[from] tracing_subscriber::filter::ParseError),
}

/// Constructs logging components based on the provided [`LoggerConfig`].
///
/// This function prepares a [`SpanStorageLayer`], and optionally file and console logging layers,
/// along with any necessary worker guards for the file and console logging layers.
/// These components are returned in a [`LoggingComponents`] struct, allowing the caller
/// to integrate them with a [`tracing_subscriber::Registry`] and other custom layers before
/// initializing the global `tracing` subscriber.
///
/// # Example
///
/// ```toml
/// [dependencies]
/// log_utils = { version = "0.1", features = ["tracing"] }
/// ```
///
/// ```
/// use std::{
///     collections::{HashMap, HashSet},
///     num::NonZeroUsize,
/// };
///
/// use log_utils::{
///     AdditionalFieldsPlacement, ConsoleLogFormat, ConsoleLoggingConfig, DirectivePrintTarget,
///     FileLoggingConfig, Level, LoggerConfig, Rotation, build_logging_components,
/// };
/// use serde_json::json;
/// use tracing_subscriber::{Layer, layer::SubscriberExt, util::SubscriberInitExt};
///
/// // Define keys for static fields
/// const SERVICE: &str = "service";
/// const ENV: &str = "env";
/// const VERSION: &str = "version";
/// const BUILD: &str = "build";
///
/// // Create static top-level fields
/// let static_fields = HashMap::from([
///     (SERVICE.to_string(), json!("my_app")),
///     (ENV.to_string(), json!("development")),
///     (VERSION.to_string(), json!("0.1.0")),
///     (BUILD.to_string(), json!("local_dev_build")),
/// ]);
///
/// let config = LoggerConfig {
///     static_top_level_fields: static_fields,
///     top_level_keys: HashSet::new(),
///     persistent_keys: HashSet::new(),
///     log_span_lifecycles: false,
///     additional_fields_placement: AdditionalFieldsPlacement::TopLevel,
///     file_config: Some(FileLoggingConfig {
///         directory: std::env::temp_dir().to_string_lossy().to_string(),
///         file_name_prefix: "my_app_log".to_string(),
///         file_rotation: Rotation::DAILY,
///         max_log_files: NonZeroUsize::new(7),
///         level: Level::INFO,
///         filtering_directive: Some("my_app=info,warn".to_string()),
///         print_filtering_directive: DirectivePrintTarget::Stdout,
///     }),
///     console_config: Some(ConsoleLoggingConfig {
///         level: Level::DEBUG,
///         log_format: ConsoleLogFormat::HumanReadable,
///         filtering_directive: Some("my_app=debug,info".to_string()),
///         print_filtering_directive: DirectivePrintTarget::Stdout,
///     }),
///     global_filtering_directive: Some("info".to_string()),
/// };
///
/// match build_logging_components(config) {
///     Ok(components) => {
///         let _guards = components.guards; // Keep guards in scope
///
///         // Build the subscriber with all components
///         let mut layers = Vec::new();
///         layers.push(components.storage_layer.boxed());
///
///         if let Some(file_layer) = components.file_log_layer {
///             layers.push(file_layer);
///         }
///         if let Some(console_layer) = components.console_log_layer {
///             layers.push(console_layer);
///         }
///
///         // Initialize the global subscriber
///         tracing_subscriber::registry().with(layers).init();
///
///         tracing::info!("Logging initialized successfully!");
///     }
///     Err(e) => eprintln!("Failed to initialize logging: {e}"),
/// }
/// ```
///
/// # Errors
///
/// Returns [`LoggerError`] if any part of the component building fails
/// (e.g., due to invalid configuration, invalid filter directives, etc.).
pub fn build_logging_components(config: LoggerConfig) -> Result<LoggingComponents, LoggerError> {
    let mut guards = Vec::new();

    let storage_layer = SpanStorageLayer::new(config.persistent_keys);

    let json_formatting_config = JsonFormattingLayerConfig {
        static_top_level_fields: config.static_top_level_fields,
        top_level_keys: config.top_level_keys,
        log_span_lifecycles: config.log_span_lifecycles,
        additional_fields_placement: config.additional_fields_placement,
    };

    // File logging
    let file_log_layer: Option<
        Box<dyn Layer<tracing_subscriber::Registry> + Send + Sync + 'static>,
    > = if let Some(file_logging_config) = config.file_config {
        let mut file_appender_builder = tracing_appender::rolling::RollingFileAppender::builder()
            .rotation(file_logging_config.file_rotation)
            .filename_prefix(file_logging_config.file_name_prefix);

        if let Some(max_log_files) = file_logging_config.max_log_files {
            file_appender_builder = file_appender_builder.max_log_files(usize::from(max_log_files));
        }

        let file_appender = file_appender_builder.build(&file_logging_config.directory)?;
        let (non_blocking_appender, guard) = tracing_appender::non_blocking(file_appender);
        guards.push(guard);

        let file_filter_directive = file_logging_config
            .filtering_directive
            .as_deref()
            .or(config.global_filtering_directive.as_deref())
            .unwrap_or_default(); // Using an empty string causes it to use the default directive

        match file_logging_config.print_filtering_directive {
            #[expect(clippy::print_stdout)]
            DirectivePrintTarget::Stdout => {
                println!(
                    "[INFO] {}: Using file filtering directive: {file_filter_directive}",
                    env!("CARGO_PKG_NAME")
                );
            }
            #[expect(clippy::print_stderr)]
            DirectivePrintTarget::Stderr => {
                eprintln!(
                    "[INFO] {}: Using file filtering directive: {file_filter_directive}",
                    env!("CARGO_PKG_NAME")
                );
            }
            DirectivePrintTarget::None => (), // Do nothing
        }

        let filter = EnvFilter::builder()
            .with_default_directive(file_logging_config.level.into())
            .parse(file_filter_directive)?;

        let layer = JsonFormattingLayer::new(
            json_formatting_config.clone(),
            non_blocking_appender,
            serde_json::ser::CompactFormatter,
        )?
        .with_filter(filter)
        .boxed();

        Some(layer)
    } else {
        None
    };

    // Console logging
    let console_log_layer: Option<
        Box<dyn Layer<tracing_subscriber::Registry> + Send + Sync + 'static>,
    > = if let Some(console_logging_config) = config.console_config {
        let (non_blocking_stdout, guard) = tracing_appender::non_blocking(std::io::stdout());
        guards.push(guard);

        let console_filter_directive = console_logging_config
            .filtering_directive
            .as_deref()
            .or(config.global_filtering_directive.as_deref())
            .unwrap_or_default(); // Using an empty string causes it to use the default directive

        match console_logging_config.print_filtering_directive {
            #[expect(clippy::print_stdout)]
            DirectivePrintTarget::Stdout => {
                println!(
                    "[INFO] {}: Using console filtering directive: {console_filter_directive}",
                    env!("CARGO_PKG_NAME")
                );
            }
            #[expect(clippy::print_stderr)]
            DirectivePrintTarget::Stderr => {
                eprintln!(
                    "[INFO] {}: Using console filtering directive: {console_filter_directive}",
                    env!("CARGO_PKG_NAME")
                );
            }
            DirectivePrintTarget::None => (), // Do nothing
        }

        let filter = EnvFilter::builder()
            .with_default_directive(console_logging_config.level.into())
            .parse(console_filter_directive)?;

        match console_logging_config.log_format {
            ConsoleLogFormat::HumanReadable => {
                let human_readable_layer = tracing_subscriber::fmt::layer()
                    .with_timer(tracing_subscriber::fmt::time::time())
                    .pretty()
                    .with_writer(non_blocking_stdout)
                    .with_filter(filter)
                    .boxed();
                Some(human_readable_layer)
            }
            ConsoleLogFormat::CompactJson => {
                let json_layer = JsonFormattingLayer::new(
                    json_formatting_config,
                    non_blocking_stdout,
                    serde_json::ser::CompactFormatter,
                )?
                .with_filter(filter)
                .boxed();
                Some(json_layer)
            }
            ConsoleLogFormat::PrettyJson => {
                let pretty_json_layer = JsonFormattingLayer::new(
                    json_formatting_config,
                    non_blocking_stdout,
                    serde_json::ser::PrettyFormatter::new(),
                )?
                .with_filter(filter)
                .boxed();
                Some(pretty_json_layer)
            }
        }
    } else {
        None
    };

    Ok(LoggingComponents {
        storage_layer,
        file_log_layer,
        console_log_layer,
        guards,
    })
}

#[cfg(test)]
mod tests {
    use std::{
        io::{self, Write},
        sync::{Arc, Mutex},
    };

    use serde_json::{Value, json};
    use tracing::{Level as TracingLevel, info, span};
    use tracing_subscriber::layer::SubscriberExt;

    use super::*;

    /// A test writer that captures output for verification
    #[derive(Clone, Debug)]
    struct TestWriter {
        buffer: Arc<Mutex<Vec<u8>>>,
    }

    impl TestWriter {
        fn new() -> Self {
            Self {
                buffer: Arc::new(Mutex::new(Vec::new())),
            }
        }

        fn get_output(&self) -> String {
            let buffer = self.buffer.lock().unwrap();
            String::from_utf8_lossy(&buffer).to_string()
        }
    }

    impl Write for TestWriter {
        fn write(&mut self, buf: &[u8]) -> io::Result<usize> {
            self.buffer
                .lock()
                .map_err(|_| io::Error::other("Mutex poisoned"))?
                .extend_from_slice(buf);
            Ok(buf.len())
        }

        fn flush(&mut self) -> io::Result<()> {
            Ok(())
        }
    }

    impl<'a> tracing_subscriber::fmt::MakeWriter<'a> for TestWriter {
        type Writer = Self;

        fn make_writer(&'a self) -> Self::Writer {
            self.clone()
        }
    }

    #[test]
    fn test_json_formatting_layer_basic_output() {
        let test_writer = TestWriter::new();
        let static_fields = HashMap::from([("service".to_string(), json!("test_service"))]);

        let config = JsonFormattingLayerConfig {
            static_top_level_fields: static_fields,
            top_level_keys: HashSet::new(),
            log_span_lifecycles: false,
            additional_fields_placement: AdditionalFieldsPlacement::TopLevel,
        };

        let layer = JsonFormattingLayer::new(
            config,
            test_writer.clone(),
            serde_json::ser::CompactFormatter,
        )
        .unwrap();

        let subscriber = tracing_subscriber::registry().with(layer);

        tracing::subscriber::with_default(subscriber, || {
            info!("Test message");
        });

        let output = test_writer.get_output();
        assert!(!output.is_empty());

        let lines: Vec<&str> = output.trim().split('\n').collect();
